// MsgServer is the server API for Msg service.
type MsgServer interface {
	// UpdateParams defines a (governance) operation for updating the module
	// parameters. The authority defaults to the x/gov module account.
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	// CreateDID registers a did:lcv DID document for the creator's own
	// address. An address may have at most one DID.
	CreateDID(context.Context, *MsgCreateDID) (*MsgCreateDIDResponse, error)
	// UpdateDID replaces the verification methods/services of the creator's
	// own DID document. Fails if the DID is deactivated.
	UpdateDID(context.Context, *MsgUpdateDID) (*MsgUpdateDIDResponse, error)
	// DeactivateDID permanently deactivates the creator's own DID. A
	// deactivated DID cannot be reactivated or updated.
	DeactivateDID(context.Context, *MsgDeactivateDID) (*MsgDeactivateDIDResponse, error)
	// AddIssuer authorizes an address to issue credentials. Authority-gated
	// (governance), per the top-level spec's "authorized issuers (added via
	// governance)".
	AddIssuer(context.Context, *MsgAddIssuer) (*MsgAddIssuerResponse, error)
	// RemoveIssuer revokes an address's authorization to issue new
	// credentials. Does not retroactively invalidate credentials already
	// issued — see modules/identity/SPEC.md.
	RemoveIssuer(context.Context, *MsgRemoveIssuer) (*MsgRemoveIssuerResponse, error)
	// IssueCredential anchors a credential hash for a subject. Only callable
	// by an address currently in the issuer registry.
	IssueCredential(context.Context, *MsgIssueCredential) (*MsgIssueCredentialResponse, error)
	// RevokeCredential flips a credential's status to revoked. Only callable
	// by the credential's original issuer or the module authority.
	RevokeCredential(context.Context, *MsgRevokeCredential) (*MsgRevokeCredentialResponse, error)
	// PresentCredential lets a holder prove control of a credential by
	// submitting a proof over the credential id. Today this is a signature
	// check (the tx signer must be the credential's subject); ZK-based
	// selective disclosure is a documented future extension point — see
	// ZKVerifier in x/identity/types/zk.go and modules/identity/SPEC.md.
	PresentCredential(context.Context, *MsgPresentCredential) (*MsgPresentCredentialResponse, error)
}

